pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNumber, address sender) public {
        vm.assume(timestamp > 0 && timestamp < type(uint256).max);
        vm.assume(blockNumber % 15 != 0);
        vm.deal(sender, 20 ether);

        // First call: succeeds for both
        vm.warp(timestamp);
        vm.roll(blockNumber);
        vm.prank(sender);
        c.fallback{value: 10 ether}();

        // Ensure pastBlockTime was updated to timestamp + 1 (ref) or timestamp + 2 (mutant)
        // The difference: with the same timestamp, the second call should revert for reference
        // but succeed for the mutant.
        bool secondCallSucceeded;
        vm.prank(sender);
        try c.fallback{value: 10 ether}() {
            secondCallSucceeded = true;
        } catch {
            secondCallSucceeded = false;
        }

        // Invariant: After one successful fallback call at timestamp T,
        // a second call at the same T must fail.
        assertTrue(!secondCallSucceeded);
    }
}

