pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNumber) public {
        // Constrain timestamp to a reasonable range and ensure block.number does not trigger the transfer (blockNumber % 15 != 0).
        // This keeps the domain wide but avoids the ether-draining path that would make the second call fail for a different reason.
        vm.assume(timestamp > 0);
        vm.assume(timestamp < type(uint64).max);
        vm.assume(blockNumber > 0);
        vm.assume(blockNumber % 15 != 0);

        // Fund a prank caller with exactly 10 ether to make one successful call.
        address caller = address(0x1000);
        vm.deal(caller, 10 ether);

        // Set block environment.
        vm.warp(timestamp);
        vm.roll(blockNumber);

        // First call: must succeed (this is a precondition, not the assertion).
        bool firstOk;
        vm.prank(caller);
        try c.fallback{value: 10 ether}() { firstOk = true; } catch { firstOk = false; }
        require(firstOk, "first call should succeed");

        // The reference now has pastBlockTime == timestamp+1.
        // The mutant has pastBlockTime == timestamp+2.
        // A second call at the same timestamp:
        //   - reference: require(block.timestamp > timestamp+1) -> false -> reverts.
        //   - mutant:    require(block.timestamp > timestamp+2) -> false -> still reverts.
        // Wait, timestamp > timestamp+2 is also false at the same timestamp.
        // To expose the difference we need a second call where the timestamp is timestamp+1 exactly.
        // That requires warping the block after the first call, which the fuzzer cannot do in a single transaction.
        // Therefore we test the invariant ON-CHAIN by deploying a re-entrant attacker that calls back immediately
        // during the fallback execution.
        // The attacker: during the first (and only) call, after c updates pastBlockTime,
        // it re-enters c.fallback with a second 10 ether payment.
        // At that re-entrant point, block.timestamp is still the same.
        // Reference: pastBlockTime = timestamp+1 after the first update, so the re-entrant require(block.timestamp > pastBlockTime) fails.
        // Mutant: pastBlockTime = timestamp+2 after the first update, so the re-entrant require also fails? No, still timestamp is not > timestamp+2.
        // So same-timestamp re-entrancy won't show the difference either, because both require pastBlockTime > block.timestamp, and block.timestamp is the same.
        // The actual difference is that the mutant's pastBlockTime is LARGER by 1, which means after a successful call the next allowable call must wait LONGER in the mutant.
        // But we cannot fuzz "wait" across transactions. We need a state invariant that can be queried after a single transaction.
        // PastBlockTime is public; we can assert its value after a successful fallback that does not trigger the transfer.
        // After the call, pastBlockTime == timestamp+1 for reference, and pastBlockTime == timestamp+2 for mutant.
        // So the invariant is: pastBlockTime == block.timestamp + 1 after a successful fallback call.
        // But that is a specific value, not a "general rule". We can phrase it as:
        // If a call succeeds (does not revert), then pastBlockTime == block.timestamp + 1.
        // However, that is still an exact equality, which the fuzzer can check directly.
        uint256 expected = timestamp + 1;
        assertTrue(c.pastBlockTime() == expected, "Invariant: pastBlockTime must equal block.timestamp+1 after success");
    }
}

