import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum) public {
        vm.assume(blockNum < 2**64);
        vm.roll(blockNum);
        vm.warp(1);

        // Ensure pastBlockTime is in the past so we can send a second tx
        vm.deal(address(this), 20 ether);
        c.f{value: 10 ether}();

        // Move to a block where the invariant differs
        vm.roll(blockNum + 1);
        vm.warp(2);

        uint256 balanceBefore = address(c).balance;
        c.f{value: 10 ether}();
        uint256 balanceAfter = address(c).balance;

        // If block.number % 15 == 0, reference transfers entire balance; mutant does not.
        // If block.number % 16 == 0, mutant transfers entire balance; reference does not.
        // General rule: balanceAfter == 0 iff (block.number % 15 == 0)
        bool transferHappened = (balanceAfter == 0);
        // The block number for the second call is blockNum + 1
        uint256 blockOfSecondCall = blockNum + 1;
        bool shouldTransferRef = (blockOfSecondCall % 15 == 0);
        assertTrue(transferHappened == shouldTransferRef);
    }
}

