pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        // Bound amounts to admissible range: at least 10 ether to pass the first require
        // and enough to not overflow the contract's balance for both calls
        amount1 = bound(amount1, 10 ether, 100 ether);
        amount2 = bound(amount2, 10 ether, 100 ether);

        // Ensure the block.number is such that transfer does NOT happen, simplifying the rule
        vm.roll(1); // block.number % 15 != 0 -> no transfer

        // First call: must use exactly 10 ether for reference
        address alice = address(0x1234);
        vm.deal(alice, amount1);
        vm.prank(alice);
        (bool ok1, ) = address(c).call{value: 10 ether}(""); // reference expects exactly 10 ether
        require(ok1, "call1 failed");

        // Second call: after advancing time
        vm.warp(block.timestamp + 2); // ensure block.timestamp > pastBlockTime
        address bob = address(0x5678);
        vm.deal(bob, amount2);
        vm.prank(bob);
        (bool ok2, ) = address(c).call{value: amount2}("");
        require(ok2, "call2 failed");

        // Rule: balance after two calls is exactly 10 ether + amount2
        // Reference: both calls succeed only if first is exactly 10 ether and second passes first require.
        // Since amount2 is bounded to >=10 ether, reference requires exactly 10 ether for first; second passes.
        // But bug: first call with 10 ether passes; second with amount2 >= 10 ether also passes.
        // Actually the difference is that the reference rejects call2 if amount2 != 10 ether because of require(msg.value == 10 ether).
        // Wait, we want a property that holds on reference for ALL inputs, but fails on buggy.
        // Let's design: we make two calls. The reference only allows exactly 10 ether each. The bug allows >=10 ether.
        // But the property should be about the final state after a sequence.
        // Instead: call fallback with amount1 (which is >=10 ether) twice.
        // Reference: first call passes only if amount1 == 10 ether; second call passes only if amount1 == 10 ether again.
        // Bug: both pass as long as amount1 >=10 ether.
        // To make a general rule: after two successful calls with the same amount, the contract balance is 2*amount.
        // This rule holds for reference because both must be exactly 10 ether, so amount is forced to 10 ether.
        // But for bug, amount could be 20 ether, and balance would be 40 ether, not forced to 20 ether.
        // However, we need to ensure both calls succeed in both versions for the rule to be checkable.
        // In reference, they succeed only if amount == 10 ether. So we need to pick amount = 10 ether to make the rule true.
        // But the fuzzer can pick any amount bounded; the rule must hold for ALL admissible inputs.
        // If the fuzzer picks amount = 20 ether, the reference fails on the first call, and we can't check the balance.
        // So we need a property that is vacuously true when calls fail, or we handle the success/failure.
        // Better: we can assert about the contract balance after two calls with the same amount, but only when both succeed.
        // A general invariant: For any sequence where both calls succeed, the final balance must be 2 * 10 ether.
        // Since in reference, both succeed only for 10 ether, the balance is always 20 ether.
        // In bug, both succeed for e.g. 20 ether, balance = 40 ether != 20 ether.
        // So we can assert: if both calls succeed, then balance == 20 ether.
        // That's a valid rule: reference always has balance 20 ether if two calls succeed (because only 10 ether each passes);
        // bug may have balance 40 ether for successful calls with 20 ether.
        // Let's implement with try/catch to check success.
    }
}

