pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 fuzzTimestamp, uint64 fuzzBlockNumber, uint96 fuzzCallValue) public {
        uint256 ts = uint256(fuzzTimestamp);
        uint256 bn = uint256(fuzzBlockNumber);
        uint256 val = uint256(fuzzCallValue);
        // Admissible: value == 10 ether for the require to pass
        val = bound(val, 10 ether, 10 ether);
        // Admissible: block.timestamp > 0, block.number in a range that includes multiples of 15
        // Let the fuzzer explore arbitrary values; we only need to allow two calls in sequence.
        vm.assume(ts > 0);
        vm.assume(bn > 0);

        // First call
        vm.roll(bn);
        vm.warp(ts);
        vm.deal(address(this), val);
        c.f{value: val}();

        uint256 firstPast = c.pastBlockTime();
        // The invariant: pastBlockTime after a successful call MUST be exactly the call's timestamp + 1.
        require(firstPast == ts + 1, "setup: first call invariant failed");

        // Second call with the same timestamp — simulates a multi-call within the same block
        // (Fuzzer can produce a second call with the same timestamp; we don't pre-filter.)
        // Re-deal because the first call may have drained the contract on mod-15 blocks.
        vm.deal(address(this), val);
        c.f{value: val}();

        uint256 secondPast = c.pastBlockTime();
        // General rule: after any successful fallback(), pastBlockTime MUST EQUAL block.timestamp + 1.
        // The buggy version allows pastBlockTime == block.timestamp in the first call's require,
        // which sets pastBlockTime = ts + 1, but the subsequent call might succeed when it should revert.
        // The invariant we assert directly: pastBlockTime after the second call must be strictly greater than ts.
        // If the buggy version allowed the second call when ts == pastBlockTime before the call (i.e., firstPast == ts),
        // then secondPast would also be ts + 1, making secondPast == firstPast, violating the strict growth.
        // Actually the reference invariant is simpler: pastBlockTime MUST equal block.timestamp + 1 after each call.
        assertEq(secondPast, ts + 1);
    }
}

